#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define CAPACITY 5

int main(int argc, char **argv)
{
    long items[CAPACITY] = {0};
    int head = 0;          // index of the first element
    int count = 0;         // number of elements currently stored

    // No command‑line arguments → the original binary prints a single NOOP line
    if (argc < 2) {
        puts("NOOP");
        return 0;
    }

    for (int i = 1; i < argc; ++i) {
        char *cmd = argv[i];

        // ----- ENQUEUE ---------------------------------------------------
        if (cmd[0] == 'E') {
            char *endptr;
            long val = strtol(cmd + 1, &endptr, 10);

            // parsing error – nothing after the 'E' or not a number
            if (endptr == cmd + 1 || *endptr != '\0') {
                puts("ERR");
                continue;
            }

            if (count == CAPACITY) {
                puts("FULL");
                continue;
            }

            // store at (head + count) % CAPACITY
            items[(head + count) % CAPACITY] = val;
            ++count;
            printf("ENQ %ld\n", val);
            continue;
        }

        // ----- DEQUEUE ---------------------------------------------------
        if (cmd[0] == 'D' && cmd[1] == '\0') {
            if (count == 0) {
                puts("EMPTY");
                continue;
            }

            long val = items[head];
            head = (head + 1) % CAPACITY;
            --count;
            printf("DEQ %ld\n", val);
            continue;
        }

        // ----- FRONT -----------------------------------------------------
        if (cmd[0] == 'F' && cmd[1] == '\0') {
            if (count == 0) {
                puts("EMPTY");
                continue;
            }

            long val = items[head];
            printf("FRONT %ld\n", val);
            continue;
        }

        // ----- UNKNOWN COMMAND -------------------------------------------
        puts("ERR");
    }

    return 0;
}
